import json, urllib.request
from pathlib import Path

cfg = json.loads(Path("/Users/mac/.cursor/mcp.json").read_text())
env = cfg["mcpServers"]["dc-platform"]["env"]
base = env["METADATA_API_BASE"].rstrip("/")
token = env["DC_USER_TOKEN"]

def get(path):
    req = urllib.request.Request(base + path, headers={"Authorization": f"Bearer {token}"})
    with urllib.request.urlopen(req, timeout=120) as r:
        return json.loads(r.read().decode())

def summarize(env_name, project, wf, want_names):
    data = get(f"/api/v1/dolphin/projects/{project}/workflows/{wf}?env={env_name}")
    tasks = data.get("tasks") or data.get("taskDefinitionList") or []
    # relations may be at top
    rels = data.get("relations") or data.get("taskRelationList") or []
    by_code = {}
    rows = []
    ds_counter = {}
    for t in tasks:
        name = t.get("name")
        tp = t.get("taskParams") or {}
        ds = tp.get("datasource")
        typ = t.get("taskType") or t.get("type")
        by_code[t.get("code")] = name
        ds_counter.setdefault((typ, ds), 0)
        ds_counter[(typ, ds)] += 1
        if name in want_names or (typ == "SQL" and len([x for x in rows if x.get("sample")]) < 3):
            rows.append({
                "name": name,
                "code": t.get("code"),
                "type": typ,
                "datasource": ds,
                "sample": name not in want_names,
            })
    # relations touching want
    want_codes = {t.get("code") for t in tasks if t.get("name") in want_names}
    touched = []
    for rel in rels:
        pre = rel.get("preTaskCode") or rel.get("pre_task_code")
        post = rel.get("postTaskCode") or rel.get("post_task_code")
        if pre in want_codes or post in want_codes:
            touched.append({
                "pre": by_code.get(pre, pre),
                "post": by_code.get(post, post),
            })
    print(json.dumps({
        "env": env_name,
        "wf": data.get("name") or data.get("wf_name"),
        "task_count": len(tasks),
        "rel_count": len(rels),
        "datasource_hist": [{"type": k[0], "datasource": k[1], "n": v} for k, v in sorted(ds_counter.items(), key=lambda kv: -kv[1])[:12]],
        "focus": rows,
        "relations": touched[:30],
        "top_keys": list(data.keys())[:30],
    }, ensure_ascii=False, indent=2))

